-- Technician time on job tasks (WMS-007, WEB-023). Tables generated by prisma migrate diff, then
-- reviewed; checks, the overlap exclusion and the immutability trigger are hand-written.

-- CreateTable
CREATE TABLE "workshop"."task_time_entry" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "job_id" UUID NOT NULL,
    "task_id" UUID NOT NULL,
    "technician_id" UUID NOT NULL,
    "started_at" TIMESTAMPTZ(6) NOT NULL,
    "ended_at" TIMESTAMPTZ(6),
    "source" TEXT NOT NULL,
    "reason" TEXT,
    "created_by" UUID NOT NULL,
    "ended_by" UUID,
    "voided_at" TIMESTAMPTZ(6),
    "voided_by" UUID,
    "void_reason" TEXT,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "task_time_entry_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "task_time_entry_job_id_idx" ON "workshop"."task_time_entry"("job_id");

-- CreateIndex
CREATE INDEX "task_time_entry_company_id_technician_id_started_at_idx" ON "workshop"."task_time_entry"("company_id", "technician_id", "started_at");

-- CreateIndex
CREATE INDEX "task_time_entry_company_id_branch_id_started_at_idx" ON "workshop"."task_time_entry"("company_id", "branch_id", "started_at");

-- CreateIndex
CREATE UNIQUE INDEX "job_task_job_id_id_key" ON "workshop"."job_task"("job_id", "id");

-- AddForeignKey
ALTER TABLE "workshop"."task_time_entry" ADD CONSTRAINT "task_time_entry_company_id_job_id_fkey" FOREIGN KEY ("company_id", "job_id") REFERENCES "workshop"."job_card"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."task_time_entry" ADD CONSTRAINT "task_time_entry_job_id_task_id_fkey" FOREIGN KEY ("job_id", "task_id") REFERENCES "workshop"."job_task"("job_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE "workshop"."task_time_entry"
  ADD CONSTRAINT task_time_entry_source CHECK (source IN ('clock', 'manual')),
  ADD CONSTRAINT task_time_entry_order CHECK (ended_at IS NULL OR ended_at >= started_at),
  -- A manual entry is a correction: it is closed, explained and at most 16 hours.
  ADD CONSTRAINT task_time_entry_manual CHECK (
    source <> 'manual'
    OR (ended_at IS NOT NULL AND reason IS NOT NULL AND ended_at - started_at <= interval '16 hours')
  ),
  -- Only closed entries are voided, always with who and why.
  ADD CONSTRAINT task_time_entry_void CHECK (
    (voided_at IS NULL AND voided_by IS NULL AND void_reason IS NULL)
    OR (voided_at IS NOT NULL AND voided_by IS NOT NULL AND void_reason IS NOT NULL AND ended_at IS NOT NULL)
  ),
  -- Nobody works two things at once: live entries of a technician never overlap (an open entry
  -- runs to infinity, so it also means at most one open entry per technician).
  ADD CONSTRAINT task_time_entry_no_overlap EXCLUDE USING gist (
    technician_id WITH =,
    tstzrange(started_at, COALESCE(ended_at, 'infinity'::timestamptz), '[)') WITH &&
  ) WHERE (voided_at IS NULL);

CREATE UNIQUE INDEX task_time_entry_one_open
  ON "workshop"."task_time_entry" (technician_id) WHERE ended_at IS NULL;

-- The entry's branch is the job's branch.
CREATE FUNCTION workshop.task_time_entry_branch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM workshop.job_card j
                  WHERE j.id = NEW.job_id AND j.company_id = NEW.company_id AND j.branch_id = NEW.branch_id) THEN
    RAISE EXCEPTION 'task_time_entry_branch_mismatch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER task_time_entry_branch BEFORE INSERT ON "workshop"."task_time_entry"
  FOR EACH ROW EXECUTE FUNCTION workshop.task_time_entry_branch();

-- Immutability: an open entry may only be closed; a closed entry may only be voided once; nothing
-- is deleted.
CREATE FUNCTION workshop.task_time_entry_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'task_time_entry_immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.id <> OLD.id OR NEW.company_id <> OLD.company_id OR NEW.branch_id <> OLD.branch_id
     OR NEW.job_id <> OLD.job_id OR NEW.task_id <> OLD.task_id OR NEW.technician_id <> OLD.technician_id
     OR NEW.started_at <> OLD.started_at OR NEW.source <> OLD.source
     OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.created_by <> OLD.created_by
     OR NEW.created_at <> OLD.created_at OR OLD.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'task_time_entry_immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.ended_at IS NOT NULL AND (NEW.ended_at IS DISTINCT FROM OLD.ended_at OR NEW.ended_by IS DISTINCT FROM OLD.ended_by) THEN
    RAISE EXCEPTION 'task_time_entry_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER task_time_entry_immutable BEFORE UPDATE OR DELETE ON "workshop"."task_time_entry"
  FOR EACH ROW EXECUTE FUNCTION workshop.task_time_entry_immutable();
